-- Additive native cash/credit ledger; preserve all historical rows and blocked drafts.
CREATE TABLE cash_adjustments(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),shift_id TEXT NOT NULL REFERENCES shifts(id),actor_id TEXT NOT NULL REFERENCES accounts(id),amount_minor INTEGER NOT NULL CHECK(amount_minor<>0 AND amount_minor BETWEEN -99999999999999 AND 99999999999999),reason TEXT NOT NULL,note TEXT NOT NULL,at INTEGER NOT NULL) STRICT;
CREATE TABLE sale_credits(sale_id TEXT PRIMARY KEY REFERENCES sales(id),customer_id TEXT NOT NULL REFERENCES customers(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),due_date TEXT NOT NULL CHECK(length(due_date)=10)) STRICT;
CREATE TABLE credit_repayments(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),sale_id TEXT NOT NULL REFERENCES sale_credits(sale_id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),method TEXT NOT NULL CHECK(method IN('Cash','Bank')),bank_method TEXT CHECK(bank_method IN('VIREMENT','CCP_BARIDIMOB')),shift_id TEXT REFERENCES shifts(id),actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL) STRICT;
CREATE TABLE credit_repayment_reversals(repayment_id TEXT PRIMARY KEY REFERENCES credit_repayments(id),command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),actor_id TEXT NOT NULL REFERENCES accounts(id),at INTEGER NOT NULL,reason TEXT NOT NULL,shift_id TEXT REFERENCES shifts(id)) STRICT;
CREATE VIEW credit_balances AS SELECT c.*,CASE WHEN v.sale_id IS NOT NULL THEN 0 ELSE c.amount_minor-COALESCE((SELECT sum(r.amount_minor) FROM credit_repayments r WHERE r.sale_id=c.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)),0) END balance_minor,CASE WHEN v.sale_id IS NOT NULL THEN 'VOID' WHEN c.amount_minor=COALESCE((SELECT sum(r.amount_minor) FROM credit_repayments r WHERE r.sale_id=c.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)),0) THEN 'PAID' ELSE 'OPEN' END state FROM sale_credits c LEFT JOIN sale_voids v ON v.sale_id=c.sale_id;
CREATE TRIGGER cash_adjustment_open BEFORE INSERT ON cash_adjustments WHEN NOT EXISTS(SELECT 1 FROM shifts WHERE id=NEW.shift_id AND state='OPEN') BEGIN SELECT RAISE(ABORT,'SHIFT_CLOSED'); END;
CREATE TRIGGER credit_repayment_cap BEFORE INSERT ON credit_repayments WHEN NOT EXISTS(SELECT 1 FROM credit_balances WHERE sale_id=NEW.sale_id AND state='OPEN' AND balance_minor>=NEW.amount_minor) BEGIN SELECT RAISE(ABORT,'OVERPAYMENT'); END;
CREATE TRIGGER credit_repayment_open BEFORE INSERT ON credit_repayments WHEN NEW.method='Cash' AND NOT EXISTS(SELECT 1 FROM shifts sh JOIN sales s ON s.store_id=sh.store_id WHERE s.id=NEW.sale_id AND sh.id=NEW.shift_id AND sh.state='OPEN') BEGIN SELECT RAISE(ABORT,'SHIFT_CLOSED'); END;
-- A settled repayment must be reversed explicitly before a credit sale can be voided.
CREATE TRIGGER credit_void_repayments BEFORE INSERT ON sale_voids WHEN EXISTS(SELECT 1 FROM credit_repayments r WHERE r.sale_id=NEW.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)) BEGIN SELECT RAISE(ABORT,'REJECTED'); END;
DROP VIEW effective_cash_movements;
CREATE VIEW effective_cash_movements AS SELECT id,command_key,shift_id,seller_id,amount_minor,reason FROM cash_movements UNION ALL SELECT sale_id||':VOID',command_key,shift_id,actor_id,-amount_minor,'SALE_VOID' FROM cash_reversals UNION ALL SELECT id,command_key,shift_id,actor_id,amount_minor,reason FROM cash_adjustments UNION ALL SELECT id,command_key,shift_id,actor_id,amount_minor,'REPAYMENT' FROM credit_repayments WHERE method='Cash' UNION ALL SELECT r.id||':REVERSE',x.command_key,x.shift_id,x.actor_id,-r.amount_minor,'REPAYMENT_REVERSE' FROM credit_repayments r JOIN credit_repayment_reversals x ON x.repayment_id=r.id WHERE r.method='Cash';
CREATE TRIGGER immutable_cash_adjustments_update BEFORE UPDATE ON cash_adjustments BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_cash_adjustments_delete BEFORE DELETE ON cash_adjustments BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sale_credits_update BEFORE UPDATE ON sale_credits BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_sale_credits_delete BEFORE DELETE ON sale_credits BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_credit_repayments_update BEFORE UPDATE ON credit_repayments BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_credit_repayments_delete BEFORE DELETE ON credit_repayments BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_credit_repayment_reversals_update BEFORE UPDATE ON credit_repayment_reversals BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
CREATE TRIGGER immutable_credit_repayment_reversals_delete BEFORE DELETE ON credit_repayment_reversals BEGIN SELECT RAISE(ABORT,'APPEND_ONLY'); END;
